import openpyxl
from copy import copy

wb = openpyxl.load_workbook('/app/spreadsheets/1_22-47_input.xlsx')
ws = wb['sheet1']

# Step 1: Collect all data rows from A:C (skip headers, empty rows)
# A header is a row where A is "ITEM" or B is "NAME" or C is "REF"
all_rows = []  # list of (item, name, ref) tuples
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=3, values_only=True):
    a, b, c = row
    # Skip header rows
    if a is not None and str(a).strip().upper() == 'ITEM':
        continue
    if b is not None and str(b).strip().upper() == 'NAME':
        continue
    # Skip empty rows
    if a is None and b is None and c is None:
        continue
    # This is a data row
    all_rows.append((a, b, c))

# Step 2: Remove duplicates (defined by identical B and C)
seen = set()
unique_rows = []
for item, name, ref in all_rows:
    key = (name, ref)
    if key not in seen:
        seen.add(key)
        unique_rows.append((item, name, ref))

# Step 3: Read helper column J
helper_names = []
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=10, max_col=10, values_only=True):
    val = row[0]
    if val is not None and str(val).strip():
        name_upper = str(val).strip().upper()
        if name_upper not in [h.upper() for h in helper_names]:
            helper_names.append(str(val).strip())

# Step 4: Sort based on helper column J
if not helper_names:
    # If J is empty, sort alphabetically A-Z by name
    result = sorted(unique_rows, key=lambda r: str(r[1]).upper() if r[1] else '')
else:
    # Group rows by name (case-insensitive matching to J)
    # Build mapping: j_name_upper -> list of rows in original order
    name_to_rows = {}
    remaining = []
    for row in unique_rows:
        name = str(row[1]).strip().upper() if row[1] else ''
        matched = False
        for jname in helper_names:
            if name == jname.upper():
                if jname.upper() not in name_to_rows:
                    name_to_rows[jname.upper()] = []
                name_to_rows[jname.upper()].append(row)
                matched = True
                break
        if not matched:
            remaining.append(row)

    # Build result: for each helper name in order, add its rows
    result = []
    for jname in helper_names:
        key = jname.upper()
        if key in name_to_rows:
            result.extend(name_to_rows[key])

    # Append remaining in original order
    result.extend(remaining)

# Step 5: Write output to F2:H20
for i, (item, name, ref) in enumerate(result):
    row_num = 2 + i
    if row_num > 20:
        break
    ws.cell(row=row_num, column=6, value=item)
    ws.cell(row=row_num, column=7, value=name)
    ws.cell(row=row_num, column=8, value=ref)

# Clear any existing values in F2:H20 that are beyond our result
for row_num in range(2 + len(result), 21):
    for col in range(6, 9):
        ws.cell(row=row_num, column=col, value=None)

wb.save('/app/output/1_22-47_output.xlsx')
print(f"Wrote {len(result)} rows to F2:H20")
for i, (item, name, ref) in enumerate(result[:19]):
    print(f"  F{2+i}: {item}, G{2+i}: {name}, H{2+i}: {ref}")

